#!/usr/bin/env python3
# Generate self-contained offline editable storyboard HTML; select suggested scene type and export JSON.
import argparse,json,pathlib,html
p=argparse.ArgumentParser();p.add_argument('plan');p.add_argument('-o','--output',default='storyboard.html');a=p.parse_args()
data=json.loads(pathlib.Path(a.plan).read_text())
# Safe embedding; the data is parsed as JSON, not executable HTML.
data_json=json.dumps(data,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
page="""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Editorial Shot Planner</title><style>
:root{color-scheme:dark;font:15px/1.45 system-ui, sans-serif}*{box-sizing:border-box}body{margin:0;background:#111318;color:#e8e9ee}header{border-bottom:1px solid #333844;padding:20px 28px;display:flex;justify-content:space-between;align-items:center}h1{font-size:21px;margin:0}.hint{color:#9a9eaa;font-size:12px}main{display:grid;grid-template-columns:1fr 1fr;height:calc(100vh - 92px)}.panel{overflow:auto;padding:22px}.right{border-left:1px solid #333844;background:#171a20}.scene{border:1px solid #3a3e4b;border-radius:12px;padding:16px;margin-bottom:14px;background:#1c2027}.scene h3{margin:0 0 8px;font-size:15px}select,textarea,input{color:#e8e9ee;background:#101218;border:1px solid #4b505c;border-radius:7px;padding:8px;width:100%;font:inherit}textarea{min-height:58px;resize:vertical}label{display:block;margin:8px 0 3px;color:#aeb5c5;font-size:12px}button{background:#396bd8;border:0;border-radius:8px;color:white;padding:11px 18px;cursor:pointer}button:hover{background:#4a7be9}.script{white-space:pre-wrap;line-height:1.8}video{width:100%;max-height:55vh;border-radius:10px;background:black}.split{display:grid;grid-template-columns:1fr 1fr;gap:12px}.pill{font-size:11px;color:#8faefa}small{color:#acb1c0} .transcript{margin-top:18px;white-space:pre-wrap} @media(max-width:850px){main{grid-template-columns:1fr;height:auto}.right{border-left:0;border-top:1px solid #333844}}
</style></head><body><header><div><h1 id="title">Shot Planner</h1><div class="hint">Review scene designs on left • View footage/transcript on right • Export approved plan</div></div><button id="export">Export JSON Plan</button></header><main><section class="panel"><div id="scenes"></div></section><section class="panel right"><label>Local raw video (optional; never uploaded)</label><input type="file" id="videoFile" accept="video/*"><video id="player" controls></video><h2>Transcript &amp; editorial beats</h2><div class="script" id="script"></div><div class="transcript" id="words"></div></section></main><script>
const plan=__DATA__;const types={AROLL:'A-roll + caption',P01:'P01 Typographic captions',P02:'P02 B-roll with text',P03:'P03 Painting animation',P04:'P04 Line and text',P05:'P05 Line and illustration',P06:'P06 Text-centric quote',P07:'P07 Center illustration',P08:'P08 Side illustration',P09:'P09 Object callout',P10:'P10 Graph and statistics'};
const el=(tag,cl='',txt='')=>{const n=document.createElement(tag);if(cl)n.className=cl;if(txt)n.textContent=txt;return n;};
document.getElementById('title').textContent=plan.title||'Shot Planner';const sc=document.getElementById('scenes');
plan.scenes.forEach((s,i)=>{const c=el('article','scene');c.append(el('h3','',s.id+' • '+(s.start_ms/1000).toFixed(2)+'–'+(s.end_ms/1000).toFixed(2)+' s'));c.append(el('div','pill',s.script||''));let l=el('label','','Scene principle');c.append(l);const sel=el('select');Object.entries(types).forEach(([k,v])=>{const o=el('option','',v);o.value=k;o.selected=k===s.principle_id;sel.append(o)});sel.onchange=()=>s.principle_id=sel.value;c.append(sel);l=el('label','','Purpose');c.append(l);const purpose=el('textarea');purpose.value=s.purpose||'';purpose.oninput=()=>s.purpose=purpose.value;c.append(purpose);l=el('label','','Design / animation notes');c.append(l);const note=el('textarea');note.value=s.notes||'';note.oninput=()=>s.notes=note.value;c.append(note);l=el('label','','Approved?');c.append(l);const approve=el('input');approve.type='checkbox';approve.checked=!!s.approved;approve.style.width='auto';approve.onchange=()=>s.approved=approve.checked;c.append(approve);sc.append(c)});
document.getElementById('script').textContent=plan.scenes.map(s=>s.id+' ['+(s.start_ms/1000).toFixed(1)+'s] '+s.script+'\n'+types[s.principle_id]).join('\n\n');document.getElementById('words').textContent=(plan.words||[]).map(w=>'['+(w.start_ms/1000).toFixed(2)+'] '+w.text).join(' ');
document.getElementById('videoFile').onchange=e=>{const f=e.target.files[0];if(f)document.getElementById('player').src=URL.createObjectURL(f)};
document.getElementById('export').onclick=()=>{const b=new Blob([JSON.stringify(plan,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=(plan.project_id||'project')+'-approved-plan.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
</script></body></html>""".replace('__DATA__',data_json)
pathlib.Path(a.output).write_text(page);print(f'Wrote {a.output}; open locally, choose footage and export revised plan')
